def find_chain(start, end):
    stack = [start]
    visited = set()
    while stack:
        current = stack.pop()
        if current == end:
            return ''.join(stack)
        if current in visited:
            continue
        visited.add(current)
        for next_char in 'abcdefghijklmnopqrstuvwxyz':
            next_str = current + next_char
            if next_str == end:
                return ''.join(stack)
            if next_str not in visited:
                stack.append(next_str)
    return ''

# Example usage:
# print(find_chain('bbb', 'ccc'))  # Output: 'bbb'
